const e=[{Claim:"One age group: contestants must be in high school and aged 12 to 18 years. The template carries one group, High School (12-18 years), for individual live vocal entries.",SourceType:"Primary - the event's own rules document",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"},{Claim:"One competition: a live singing performance in front of a panel of judges and an audience, held on Friday 16 June 2023 at Melton Town Hall, Victoria, Australia. Entry follows a video audition and two nominated song options; the organiser picks one song for the live performance. Contestants who pass the audition perform live; entry is not guaranteed on application.",SourceType:"Primary - the event's own rules document",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"},{Claim:"Judges score each performance out of 40 on four criteria (Vocals, Song Choice, Performance, Audience Engagement), each printed as 8/10 in a scoring example. The template sets the maximum score to 40.",SourceType:"Primary - the event's own rules document",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"},{Claim:"NO JUDGING CRITERIA ARE INSTALLED. The four criteria are printed only as an example out of 10 each, a total of 40 rather than 100, so they cannot be installed as criteria that total exactly 100. Panels can score on the four named criteria and enter the total out of 40.",SourceType:"Scope note - printed marks do not total 100",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"},{Claim:"No placing points, grades or mark bands are printed. First, second and third place prizes are printed as money (350, 250 and 50 dollars plus certificate, trophy and gift card for the winner), so no ranks or grades are installed.",SourceType:"Scope note - nothing printed to build from",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"},{Claim:"Rules the platform has no field for are left out: video audition review, two song options, the need for a parent or guardian under 18, the unsigned-performer condition, health testing on arrival, audience voting not affecting the scores, and the entry fee of 10 dollars (fee set to zero for the organiser to fill in).",SourceType:"Scope note - rules with no matching field",Source:"M.D.C High School Talent Battle 2023 competition info sheet (Melton FReeZA, 3337 Production, with Melton Young Communities)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"}],t="Built from the M.D.C High School Talent Battle 2023 info sheet (3 pages, text checked against the original PDF). One age group (12-18) and one item (singing) are printed. Scored out of 40 on four criteria; these total 40, not 100, so no judging criteria are shipped and the maximum score is 40. No ranks or grades are printed. The single time-sheet, venue seating, ticket prices, audition, fee and terms are not representable and are covered in the registration content. The event is a single council-run event (2023 edition).",o=[{GroupName:"High School (12-18 years)",AgeFrom:12,AgeTo:18,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/teen.webp"}],i=[{CompetitionItem:0,Title:"Singing",Category:106,CategoryCategoryName:"Music",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-singing.webp",TimeCalculation:"PerHead"}],n=[{CompetitionItem:0,CompetitionItemTitle:"Singing",Group:0,GroupGroupName:"High School (12-18 years)",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:1,LanguageLanguageName:"English",Fees:0,MaximumMinutes:0,MaximumScore:40,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/solo-singing.webp"}],a={Evidence:e,MaintenanceNote:t,AgeWiseGroups:o,CompetitionItems:i,CompetitionsAssignedToGroup:n};export{o as AgeWiseGroups,i as CompetitionItems,n as CompetitionsAssignedToGroup,e as Evidence,t as MaintenanceNote,a as default};
